    allowed = {"_documents", "_inventory", "verify_cached_bundle", "materialize_bundle"}

    def protected(data):
        lines = data.splitlines(keepends=True)
        nodes = [
            node
            for node in ast.parse(data).body
            if isinstance(node, ast.FunctionDef) and node.name in allowed
        ]
